var nums = [2, 2, 1, 1, 1, 2, 2];
var candidate = null;
var count = 0;
nums.forEach(function (n) {
  if (count === 0) {
    candidate = n;
  }
  count += n === candidate ? 1 : -1;
});
console.log(candidate);
